use std::fs

fn is_int(t: string) -> bool {
    let n: int = t.len() as int
    if n == 0 { return false }
    let mut start = 0
    if t[0..1] == "-" { start = 1 }
    if start >= n { return false }
    let mut i = start
    while i < n {
        let c = t[i..i + 1]
        if c < "0" || c > "9" { return false }
        i += 1
    }
    true
}

fn to_int(t: string) -> int {
    let n: int = t.len() as int
    let mut neg = false
    let mut i = 0
    if t[0..1] == "-" {
        neg = true
        i = 1
    }
    let mut v = 0
    while i < n {
        let d = t[i..i + 1]
        let mut k = 0
        while k < 10 {
            if d == "${k}" { v = v * 10 + k }
            k += 1
        }
        i += 1
    }
    if neg { 0 - v } else { v }
}

fn eval(line: string) -> string {
    let mut st: Vec<int> = []
    for t in line.split(" ") {
        if t == "" { continue }
        if t == "+" || t == "-" || t == "*" || t == "/" {
            if st.len() < 2 { return "error: underflow" }
            let b = st.pop().unwrap_or(0)
            let a = st.pop().unwrap_or(0)
            if t == "+" { st.push(a + b) }
            else if t == "-" { st.push(a - b) }
            else if t == "*" { st.push(a * b) }
            else {
                if b == 0 { return "error: divzero" }
                st.push(a / b)
            }
            continue
        }
        if !is_int(t) { return "error: token" }
        st.push(to_int(t))
    }
    if st.len() != 1 { return "error: leftover" }
    "${st[0]}"
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.lines() {
        if line.trim() == "" { continue }
        println(eval(line))
    }
}

